lemma arm_mass_lower_of_latentArmPositivity {k dx dz : ℕ} {pi0 : ℝ}
    (P : Measure (FullData k dx dz)) [IsProbabilityMeasure P]
    (hpos : LatentArmPositivity (pi0 := pi0) P) (t : Bool) :
    k * pi0 ≤ P.real {w | w.T = t}
